const tabId = 1148881640;
const fields = await browserjs(tabId, () => {
  const labels = Array.from(document.querySelectorAll("label, .MuiFormLabel-root, .MuiInputLabel-root"));
  return labels.map(l => {
    const parent = l.closest(".MuiFormControl-root") || l.parentElement;
    const inputs = Array.from(parent ? parent.querySelectorAll("input, [role='combobox']") : []).map(i => ({
      tag: i.tagName,
      id: i.id,
      name: i.name,
      value: i.value,
      role: i.getAttribute("role")
    }));
    return {
      labelText: l.innerText?.trim(),
      inputs
    };
  });
});
console.log(JSON.stringify(fields, null, 2));

